describe('a conversation-list request', () => {
  it('answers with the socket user’s summaries, dated as ISO strings, off the turn path', async () => {
    const created = new Date(Date.UTC(2026, 2, 1, 9));
    const touched = new Date(Date.UTC(2026, 2, 2, 10));
    const asked: unknown[][] = [];
    const store = {
      listFor: (...args: unknown[]) => {
        asked.push(args);
        return [{sessionId: 'older', createdAt: created, updatedAt: touched, entryCount: 4}];
      },
    };
    const sent: OutgoingMessage[] = [];
    const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
    const owner: ChatSession = {sessionId: 'current', userId: 'owner', entries: []};
    const cursor = {sessionId: 'z9', updatedAt: '2026-03-05T00:00:00.000Z'};

    await createMessageHandler({} as ChatOrchestrator, store)(ws, owner, {
      type: 'list_sessions',
      userId: 'intruder',
      limit: 2,
      before: cursor,
    });

    expect({asked, sent}).toEqual({
      asked: [['owner', {limit: 2, before: cursor}]],
      sent: [
        {
          type: 'session_list',
          sessions: [
            {sessionId: 'older', createdAt: created.toISOString(), updatedAt: touched.toISOString(), entryCount: 4},
          ],
        },
      ],
    });
  });
});
EOF
